independent_behavior_check_sources.receipt-location:
import assert from 'node:assert/strict'; import {pathToFileURL} from 'node:url'; import path from 'node:path';
const load=async f=>import(pathToFileURL(path.join(process.argv[1],f)).href);
const {checkout}=await load('src/app.js'); const {makeReceiptKey}=await load('src/billing/receipt.js');
assert.equal(makeReceiptKey({accountId:'acme',sequence:7}),'invoice/acme/0007');
const invoice={accountId:'acme',sequence:7}; let captured;
const result=await checkout(invoice,{post:(...args)=>{captured=args;return 'provider-result';}});
assert.equal(result,'provider-result'); assert.deepEqual(captured,['/invoices',invoice,{'Idempotency-Key':'invoice/acme/0007'}]);
assert.equal((await load('src/reports/receipt.js')).makeReceiptKey({id:7}),'report:7');
assert.equal((await load('src/transport/receipt.js')).makeReceiptKey({headers:{'x-receipt':'response-receipt'}}),'response-receipt');
console.log(JSON.stringify({status:'passed',checks:['actual checkout outbound path/body/header and result','owner key for required example','report and response helper distinction']}));

independent_behavior_check_sources.inventory-contract:
import assert from 'node:assert/strict'; import {pathToFileURL} from 'node:url'; import path from 'node:path';
const load=async f=>import(pathToFileURL(path.join(process.argv[1],f)).href);
const {importStock}=await load('src/entry.js'); const {parseStock}=await load('src/input/csv.js');
const {normalizeStock}=await load('src/domain/stock.js'); const {canonicalSku}=await load('src/domain/sku.js'); const {wireStock}=await load('src/output/wire.js');
assert.deepEqual(parseStock(' ab-2 ,5,8'),{sku:'ab-2 ',available:5,reserved:8});
assert.equal(canonicalSku(' ab-2 '),'AB-2'); assert.deepEqual(normalizeStock({sku:' ab-2 ',available:5,reserved:8}),{sku:'AB-2',count:0});
assert.deepEqual(wireStock({sku:'AB-2',count:0}),{product_code:'AB-2',units:0,schema:2});
for(const [input,units] of [[' ab-2 ,5,8',0],[' q ,8,2',6],[' q ,-5,2',0],[' q ,-5,-8',3]]) assert.deepEqual(importStock(input),{product_code:input.includes('ab-2')?'AB-2':'Q',units,schema:2});
for(const input of ['x,no,1','x,1,no','x,Infinity,0']) assert.throws(()=>importStock(input),{message:'invalid count'});
console.log(JSON.stringify({status:'passed',checks:['active parser/domain/SKU/wire contracts','reserved subtraction before clamp including negative inputs','required full output and exact invalid count error']}));

independent_behavior_check_sources.dispatch-ambiguity:
import assert from 'node:assert/strict'; import {pathToFileURL} from 'node:url'; import path from 'node:path';
const load=async f=>import(pathToFileURL(path.join(process.argv[1],f)).href);
const {dispatch}=await load('src/dispatch.js'); const {registry}=await load('src/registry.js');
assert.equal(Object.getPrototypeOf(registry),null); assert.deepEqual(Object.keys(registry).sort(),['audit','mail']);
assert.equal(registry.mail,(await load('src/channels/mail.js')).handle); assert.equal(registry.audit,(await load('src/channels/audit.js')).handle);
assert.equal(dispatch({kind:'mail',payload:' Hi '}),'mail:hi'); assert.equal(dispatch({kind:'audit',payload:{a:1}}),'audit:{"a":1}');
for(const kind of ['legacy','toString','__proto__','missing']) assert.throws(()=>dispatch({kind,payload:3}),{message:'unknown kind'});
assert.equal((await load('src/preview.js')).preview('x'),'legacy:x');
console.log(JSON.stringify({status:'passed',checks:['registry keys, null prototype, exact registered function identities','mail selection/output and audit alternate output','unknown kinds including inherited names rejected','legacy available to preview but absent from dispatch registry']}));

independent_behavior_check_sources.zero-quantity:
import assert from 'node:assert/strict'; import {pathToFileURL} from 'node:url'; import path from 'node:path';
const load=async f=>import(pathToFileURL(path.join(process.argv[1],f)).href);
const {lineFromRequest}=await load('src/api.js'); const {parseQuantity}=await load('src/quantity.js'); const cli=(await load('src/cli.js')).parseQuantity;
const good=[0,'0',' 0 ',1,'2',23,' 42 ','1e2'];
for(const value of good){ assert.equal(parseQuantity(value),Number(value)); assert.deepEqual(lineFromRequest({sku:' A ',quantity:value}),{sku:'A',quantity:Number(value),active:Number(value)>0}); }
const bad=[-1,'-1',0.5,'0.5',NaN,Infinity,-Infinity,'Infinity','NaN','',' ','\t\n','\u00a0',true,false,null,undefined,'oops'];
for(const value of bad){for(const run of [()=>parseQuantity(value),()=>lineFromRequest({sku:'A',quantity:value})]) assert.throws(run,e=>e instanceof Error && e.name==='Error' && e.message==='invalid quantity');}
for(const [input,expected] of [[0,1],['0',1],['4',4],['oops',1]]) assert.equal(cli(input),expected);
console.log(JSON.stringify({status:'passed',checks:['shared parser and API for numeric/string zero and positive integer compatibility','direct parser and API rejection for every required invalid class including Unicode whitespace','Error class and exact message','CLI legacy examples unchanged']}));
